            (
                a
                for a in reversed(actions)
                if str(a.get("decision_id")) == fid and a.get("channel") == "call" and a.get("at")
            ),
            None,
        )
        evidence = [
            {
                "source": s.get("source"),
                "value": s.get("value"),
                "doc": s.get("doc"),
                "page": s.get("page"),
