def parse_ts(value: Any) -> datetime | None:
    if not value:
        return None
    try:
        dt = datetime.fromisoformat(str(value).replace("Z", "+00:00"))
    except ValueError:
        return None
    return dt if dt.tzinfo else dt.replace(tzinfo=tz())


def read_json(name: str, default: Any) -> Any:
    path = state_dir() / name
    try:
        return json.loads(path.read_text(encoding="utf-8"))
    except (OSError, json.JSONDecodeError):
        return default


def write_json(name: str, data: Any) -> None:
    path = state_dir() / name
    path.parent.mkdir(parents=True, exist_ok=True)
    tmp = path.with_suffix(f".{uuid.uuid4().hex[:6]}.tmp")
    tmp.write_text(json.dumps(data, ensure_ascii=False, indent=2), encoding="utf-8")
    tmp.replace(path)


def read_list(name: str) -> list[dict]:
    data = read_json(name, [])
    if isinstance(data, dict):
        for key in ("items", name.removesuffix(".json")):
            if isinstance(data.get(key), list):
                return data[key]
        return []
    return [x for x in data if isinstance(x, dict)] if isinstance(data, list) else []


def read_csv(path: Path) -> list[dict]:
    try:
        with path.open(encoding="utf-8-sig", newline="") as fh:
            return list(csv.DictReader(fh))
    except OSError:
        return []


def num(value: Any) -> float | None:
    try:
        return float(str(value).replace(",", "").replace(" ", ""))
    except (TypeError, ValueError):
        return None


# ---------------------------------------------------------------- map: nodes, legs, shipments

# World geography, not Soony data: the usual deep-sea lane from East Asia to North Europe, east to
# west. Used only when a route's `via` port is missing from ports.csv or the route has no
# waypoints of its own. Only lane points west of the origin are used.
SEA_LANE = [
def _n(n: float | None) -> str:
    return f"{n:,.0f}" if n is not None else "unknown"


def _hm(dt: datetime, cur: datetime) -> str:
    """'06:12' today, 'Sat 20:50' on another day."""
    tz = _api().tz()
    d = dt.astimezone(tz)
    return d.strftime("%H:%M") if d.date() == cur.astimezone(tz).date() else d.strftime("%a %H:%M")


def plural(name: str | None) -> str:
    """'Game Card 128 GB' -> 'game cards', 'Statue "The Getaway"' -> 'statues', "Collector's
    Box" -> "collector's boxes"; codes keep their case."""
    if not name:
        return "parts"
    base = name.split('"')[0].strip() or name
    words = base.split()
